    "steps": "从出生第一天起，大人就可以用手挠挠宝宝的脸蛋、胸脯、胳 肢窝、小脚丫等身体部位，并冲着他笑。宝宝首先感觉到快乐的气氛，看懂了大 人的表情，感到身体的痒痒，综合这些条件，渐渐宝宝的目光柔和，口角向上而 出现笑容。这种结果要经过大概两周才出现，要经过大人的逗弄才能引出，与新 生儿在睡前出现的笑容不同，新生儿在睡前面部肌肉放松出现的笑是无意识的动 作。而逗笑是一种条件反射，有大人的逗弄，引起宝宝快乐的情绪，而出现的动 作是有意识的。宝宝被逗笑即是能够成立条件反射，说明宝宝能够学习了，所以 越早被逗笑的宝宝就越聪明。\n「美」伊林沃恩观察一例出生后第三天被逗笑的宝宝，6 岁时智商为 180。我曾 看到出生第5天被逗笑的宝宝，4岁时智商128，后来发现他有良好的数学能力。",
    "tips": "注意：每天都要定时逗宝宝笑，方法大致相同，才容易成功。当宝宝被逗笑 时，马上拍下照片，写上时间和经过作留念。"
