    "duration": "10分钟",
    "steps": "通过观察，大概在两周时宝宝大便相对定时，经常在早晨吃饱 之后。大人做好准备，待宝宝吃饱后，抱起，坐位把宝宝，便盆放在适合处，大 人用声音“嗯”做引导，让宝宝排泄。经过几天，偶然有一天成功了就要把宝宝 抱起来亲亲，并说：“真乖”，使宝宝懂得这样做会使大人高兴。以后宝宝看到便 盆，在把便的姿势下就会产生排泄的反射。经过两周的学习，多数宝宝会在满月 前识把，如果要排泄会用身体的摆动或习惯的动作表示，使大人及时来把。白天 尽量用布的尿布，晚上用有吸湿性性能的纸尿裤，可以减少晚上频繁更换的次数， 白天把大小便可以增加与宝宝接触，同时使宝宝建立一种新条件反射。",
    "tips": "有的宝宝识把早，有的宝宝识把较晚。自从纸尿裤普及以来， 多数家庭都不用把的方法了，到了两岁后许多妈妈都埋怨不用纸尿裤比断奶更难， 因为宝宝没有入厕的习惯，培养十分困难。其实白天把便，晚上用纸尿裤，并不 费事。多数宝宝在7～10天内就学会，而且宝宝做出信号让大人把便，两个人彼 此合作能增进感情。宝宝觉得有人关心自己，不但有安全感，同时也能主动发出 信号促进与人交往，以后学习语言比较主动。识把宝宝膀胱括约肌得到锻炼，以 后排泄自理比较容易。\n注意：把便时大人不宜向前弯腰，以免压迫宝宝的呼吸。此外应观察宝宝的 需要，不要把便过勤，使膀胱有空虚和满盈的不同感觉，让宝宝自主做出排便信 号。"
