    "tips": "大人鼓励性地同他对着说，慢慢这个音就学会了。宝宝此时都 是随意的发音，还未能模仿。不过大人经常同他说话，把他发的音录下来播放给 他听，能促进宝宝多发音，发音练习是为以后学说话做准备的。如果不诱导宝宝 发音，将来宝宝说话会延迟。（注：元音a、e、i、o、u）"
