    "tips": "晚上连续睡眠，夜间睡眠时间延长，学会分开昼夜，是暗适应 和条件反射形成的结果，宝宝能逐渐接近大人的生活规律，会让父母得到休息。 注意有时偶然一次半夜醒来哭闹几声，也要坚持拍拍让宝宝再入睡。如果偶然的 哭闹就马上喂奶，以后每天就会到时要喂，再形成半夜喂奶的条件反射，又要从 头开始使睡眠时间延长。这种情况在1岁以内会经常反复，尤其是遇到有病时会 困难一些，甚至3岁前都会反复。如果妈妈能果断一些，晚上醒来只给水喝，尽 量不喂奶，就会减少许多麻烦。"
