    "steps": "140天前后妈妈抱宝宝坐台灯旁，用手拧开台灯时说：“灯， 灯”，再关掉台灯，看着宝宝的视线是否看着灯。如果还未注意到，就多开关几 次，让光的变化吸引宝宝看着台灯。然后妈妈说：“灯，灯”，拿着宝宝的手摸摸 灯罩，摸摸开关，还可以拿着宝宝手，让宝宝开灯、关灯。妈妈抱着宝宝离开桌 子，走到房间的另一头，宝宝：“灯呢?”，看宝宝是否用眼看着灯。如果不会， 从头再来；如果会看着灯的方向，妈妈又再走到另一边，问宝宝：“灯呢?”，看 宝宝是否盯着灯的方向。如果几次都看对，千万别忘记下午再问。如果宝宝忘记 了可以从头再教，如果宝宝已经学会了，连续几天都要复习，巩固记住已经认识 的第一种东西。有些宝宝不爱看灯，可以让他先学认上个月他会听声拍打的大玩 具。",
    "tips": "平日观察宝宝爱看什么，让他学认他爱看的东西，就容易 成功。如果不成，过1～2 个礼拜再教也可以。一定在宝宝高兴时让他学习，如 果宝宝啼哭了，大人可以多等几天，千万不能强迫。如果宝宝学会了要马上称赞， 让他有成功的喜悦，下次就更加乐意学习。如果被大人勉强，或者留下不愉快的 印象，下次宝宝会拒绝学习。当大人说某件物名时，如果宝宝听懂了就会用目光 盯着大人说的东西。如果印象很深，每次说物名时都会看目标；如果还有怀疑， 就会有时看有时不看；偶然看到一眼就表示宝宝曾听过，还未记住；完全不看就 是宝宝从来未学过。许多家长以为等宝宝长大自然会，不必让他先学。一般3～ 5个月时宝宝的视皮层细胞的联系正达高潮期，如果能与听觉联系就能开始学习 了。不过每个宝宝的情况不同，不能勉强，要让宝宝高兴时认他所喜欢的东西。 如果不行就迟一两周也不要紧，但不可不教。"
