    "duration": "10分钟",
    "steps": "让宝宝坐在大人的膝盖上，两人面向前方，大人一面背诵 儿歌，一面按着节拍上下颠动膝盖，让宝宝感到如同骑在马上。大人念道：\n骑大马，骑大马，\n上高山，跨过河。\n咯噔咯噔，跨过河!\n念到“咯噔咯噔”时把宝宝抱起，到跨过河时把他举高让他有跨过河的感觉。\n宝宝很喜欢这种有韵律的游戏，练习几次后，当听到“咯噔咯噔”时宝宝会做准 备，一听到“跨过河”时身体就会向高处跃，配合大人的动作。\n另一首儿歌如：\n小老鼠，上灯台，\n偷油吃，下不来，\n叫妈妈，妈不在，\n叽哩咕噜滚下来!\n当念到“叽哩咕噜”时让宝宝做好准备，一说到“滚下来”时，把宝宝的身 体向前倾做滚下来的动作。",
