    "steps": "如果家中来了客人，以往宝宝会对客人笑，表示打招呼。 到了 6个月，宝宝改变了常态，看到陌生人会产生悲伤、害怕等情绪。这是因为 宝宝懂得了躲开生人以避免危险，宝宝会转过头把脸藏在妈妈的怀里，探出头来， 观察客人的动静。如果客人曾经来过，宝宝会盯着他看，保持警惕，多看几次后， 目光渐渐缓和，如果发现客人没有恶意，才肯接受客人拿着的玩具，对客人笑笑。 过几天，再见到这个客人时，如果客人对宝宝笑笑，有时宝宝肯让客人抱，但是 过几秒钟，宝宝又马上要回妈妈怀中。来回几次客人就变成熟人，宝宝开始对生 人适应。同样宝宝对新的环境也会害怕，如果新的环境中有些玩具或有些好看的 图画，宝宝会多看一会儿，渐渐旁边的东西也开始注意。如果发现有更多好看的 或好玩的东西，宝宝就愿意留下来玩一会儿。多接触几次，就能留下来久一些。 如果妈妈经常带宝宝接触新的环境，以后宝宝很愿意出去，会用手指着想要去的 地方。",
