    "steps": "用一个有转盘的玩具电话，让宝宝食指探入洞内，拨动转 盘；把一个小珠子(直径2厘米)放入一个口径2.5 厘米的小瓶内，让宝宝用食指 把珠子抠出来；如果家中的地垫是泡沫塑料，上面有镶嵌的花纹，让宝宝用食指 抠动花纹。宝宝最喜欢玩电视机的遥控器，平时未开电视时可以让宝宝用食指按 凸出来的按键，有时开着电视也可以让他去按一下，当他看见电视屏幕变了会十 分惊讶。家里的台灯按键也让宝宝用食指压按，他会发现灯亮了，再压按一下灯 就灭了，而且宝宝会反复练习，这是因为宝宝在探究动作的因果关系。",
    "tips": "巧巧食指，可以测试宝宝手指的灵活性。有时宝宝可以用 两只手的食指轮流操作， 但大多数是集中在利手的食指上。宝宝会模仿大人用 食指操作，如转盘、按键、从瓶中取出糖果、从小袋里抠出玩具等，这些精细的 操作，经过反复练习8 个月的宝宝一般都能做到，而且能促进宝宝智力的发展。"
