    "prep": "刚开始时，孩子可能只是微微举起手来，似乎并未意识到 自己的动作；或者，他会把手指头一松一紧地抓放。这个时候，他还不能同时一 边说“再见”及一边“挥手”。最好让他自由发展，千万不要操之过急。等孩子学会 说再见与挥手后，只要再过几个星期，他就能把两者结合在一起了。那时候，孩 子可能会很喜欢和别人挥手打招呼了!",
    "duration": "出门外出时",
    "steps": "教师指导家长在离开孩子的房间时，可以把手放在脸旁， 向宝宝挥一挥手，对宝宝说“再见”，同时，让宝宝能看到家长手部和嘴部的动作。 有的时候，家长可以一边说“再见”，一边轻轻扶住宝宝的手，做出挥手的动作。 如果宝宝的家人时常对宝宝微笑说再见，将来他会比较容易与他人相处。",
    "tips": "或者，你抱着他在外面散散步，向过往的邻居挥手，他们 大都会很乐意和你的孩子打招呼的。离开宝宝时，向他挥挥手说再见。可能需要 一段很长的时间，宝宝才会对你这个动作有所反应。不过，一旦他在你“挥手” 说“再见”时，也能回报你同样的动作和类似的声音，你会觉得万分自豪。提供榜 样，让宝宝学会挥手说再见。如果宝宝的举动得到大人愉快的反应，他便会一再\n重复。"
