    "tips": "过去的几个月，完全由大人把持着大小便，到 8个月后， 应当让宝宝自己坐在便盆上大小便，可以由大人扶持，但是要让宝宝认识便盆， 知道便盆是大小便的地方，不能随便蹲下就地大小便，养成良好的卫生习惯。"
