    "tips": "基本上在 6个月能发出4 个以上辅音的宝宝都会称呼第一 个大人。在 6～8个月时宝宝也会发出叫“爸爸”和“妈妈”的声音，这时是无 意义的发音，不是看见亲人时才发出的。9～10个月如果看见爸爸时叫“爸爸”， 或看见妈妈时叫“妈妈”，这才是有意义的见人才称呼的发音，这两者有明确的 区别。第一次有意义的口头表达，是说话的开始。注意：一般男孩比女孩称呼大 人略微迟一些，因为管理说话的语言运动中枢发育相对迟一些。语言理解中枢比 语言运动中枢发育早半年，所以宝宝懂话在先，说话在后。大人要注意观察宝宝 是否能认人认物，能否听懂大人说的话，听懂了就行，不必计较宝宝称呼大人的 早和晚，到 14 个月才会称呼大人的宝宝都属正常范围。坚持用夸张的口形同宝 宝说话，他会通过模仿渐渐学会说话。"
