    "tips": "强壮的宝宝扶物站稳后就会左右迈步，或者只向一面迈步， 体弱的宝宝扶站不稳，还要靠着家具，自然不敢迈步，要经过一番练习才敢迈出 1～2 步。宝宝学站立的过程中最主要是用脚负重，还未能用双脚负重的宝宝会 用双手扶物，用背靠家具帮助自己站稳。开始迈步时，需要短时间的单脚负重， 对于 9个月的宝宝已经是够难的了。所以家长应注意，因为此时宝宝双腿还不能 负重，不要让宝宝长久站立，以免使宝宝双腿弯曲。"
