    "duration": "3分钟",
    "steps": "教师指导家长给宝宝看一个铃铛或其他小型的玩具。然后， 家长把手心朝下．让铃铛掉下来。宝宝会喜欢那种声音，也想自己试试看。家长 也可以拿一个小皮球给他，当小球弹跳时，可以吸引宝宝多丢几次。家长还可以 试试不同的方式，让宝宝练习手指动作。教宝宝练习控制手部肌肉时，可以先教 他懂得“放手”的意义。张开和合拢手指是两个相反的动作，控制手部动作是需要 好好学习的。只有当宝宝双手能控制自如后，才能开始练习吃饭，也才有掌握周 遭的东西、扩展探索的可能。小宝宝还不会玩积木，是因为他还不能灵活地控制 手指的活动。",
    "tips": "玩这个游戏时，你最好用一个会响的球或铃铛，因为它 掉下来时会发出声音，这样小孩会玩得更起劲。让落下的距离大些，这样孩子才 能同时看清楚你的手和落下的玩具。在示范几次以后，把玩具交给孩子，让他试 试看。对孩子来说，前几次可能很困难，因此要多鼓励他。"
