    "tips": "一般1岁的宝宝都会学猫、狗、鸟、鸭或牛、羊等动物的 叫声，学动物叫是宝宝们愿意做的事，因为大多数宝宝都喜欢动物，去看动物时， 都会学它们叫，以表示亲近。模仿发音是学语言很重要的一步，大人要鼓励宝宝 学动物叫。"
