    "prep": "室内外较为安静的环境均可，如大床、地毯、草地、草场 等。准备宝宝平时经常接触并喜爱的各种毛绒玩具。",
    "duration": "5分钟",
    "steps": "教师指导家长把各种玩具放在宝宝四周，但应注意放在宝 宝的视线范围内。引导宝宝，发生互动。如“把小兔带到我这里来好么？”（注： 表达同等意思有多种方式）等宝宝拿来，放在爸妈手中，爸妈对宝宝说“谢谢”。 继续发出指令：如“带小兔到娃娃家做客好么？”“让小兔去摇篮里睡觉好么？” 等。看宝宝是否能正确理解所说地点的含义，及其动作是否正确。用同样的方法 利用不同的玩具反复游戏，看宝宝是否熟悉及正确理解不同玩具的名称。",
    "tips": "游戏熟练之后，所选的物体可以增多，如添加日常真实物 品，以扩展宝宝的名词感知；指令可以多样化，如“给小兔穿衣服”，“喂小兔吃 饭”等，帮助宝宝提高理解能力。要注意以下要点：\n1． 应当选择宝宝经常接触到且熟悉的玩具，并能理解玩具名称的指代，但 不强求宝宝在没有爸妈帮助的情况下说出玩具的名称。\n2． 游戏开始时，不要选择数量过多的玩具，1～2 个即可。宝宝熟练后， 可考虑适当增加玩具的数量和种类，以帮助宝宝提高理解力。\n3． 游戏时最主要的是宝宝的兴趣及耐心。如果宝宝表现出不愿意继续或厌 烦的情绪，爸妈不应强迫；在宝宝玩得十分投入而不愿意停止时，爸妈也不要随 意中止，可采取其他的方式自然退出。"
