    "prep": "鸡妈妈活动图片；小鸡饰每个宝宝一个；每个宝宝两个碗、 两个小勺。塑料垫子若干块。找一名教师或家长扮演鸡妈妈。",
    "duration": "10-20分钟",
    "steps": "教师指导宝宝坐在垫子上，小宝宝，你们看，谁来了？让 宝宝看鸡妈妈的活动图片。啊，原来是鸡妈妈。“小宝宝,你们听，鸡妈妈对我们 说什么？”教师打开录音机：“小宝宝，你们好，我是鸡妈妈，现在果园里各种 水果都成熟了，今天，我想请咱宝宝到我家去做客，去品尝各种水果，小宝宝， 赶快来吧！”教师说:“啊，原来是鸡妈妈想请咱们去做客。”教师带领小宝宝到 鸡妈妈家门口要先敲门，见到鸡妈妈要先说“鸡妈妈好”。引导宝宝说“鸡妈妈 你好”。 鸡妈妈说“小宝宝们好，今天我给你们准备了各种水果，现在请小宝宝 们品尝各种水果吧！”此时，引导宝宝说“谢谢鸡妈妈”。然后教师和家长一起拿 着小碗和小勺模仿吃水果的动作，在宝宝模仿吃水果的过程中，教师和家长要对 宝宝进行各种良好习惯的教育，教育宝宝吃东西时，不要讲话，宝宝模仿吃完水 果后，引导宝宝与鸡妈妈说“再见”。",
    "tips": "在整个的教育活动中，教师和家长将礼貌做客贯穿于整个 教育活动中，这样，不仅使宝宝获得了快乐，同时使宝宝懂得了基本的礼貌用语。"
