    "steps": "分两步进行。第一步，让宝宝把鞋带的硬头插进珠洞内， 然后大人帮助把绳子拉出来。等宝宝把这一步骤学会了，再做下一步。第二步， 大人把绳子的硬头插进珠洞，让宝宝从洞口的另一端把绳子拉出，然后让宝宝重 复第二个步骤，待宝宝分别学会两个步骤后，再把两个步骤连接起来完成整个过 程。此阶段只要求宝宝能穿上 1～2个珠洞，熟练后，让宝宝练习穿珠子，逐渐 增加珠子的个数。虽然比用棍子穿套塔难一些，但是道理是一样的。",
    "tips": "手巧的宝宝 5分钟内能穿上3颗珠子。未练习的宝宝就不 会穿，失败的原因常常是穿进去后没有及时从珠子的另一端把绳子取出来，绳子 从进口处掉了下来。这个测试往往女孩子比男孩子做得好些，这是因为女孩子的 手比较巧，做事比较细致，此外练习的次数也很重要，多练习才能穿得多、穿得 快。"
