    "tips": "巩固爬行能力是为正好的行走做基础。如果宝宝周岁时还 没有开始走路，那么一岁半以前他应该学会。事实上，2岁期间的主要成就是掌 握完美的走路技能。如果他已经开始学习走路，可能还要 1～2 个月时间，他才 能不需要何帮助地站立和顺利行走。然而，不要期望他按照你想像的方法去做。 他的做法是：把手放在地上，伸直胳膊，高高地撅起屁股，然后将腿拉到身子下 面。最后，直起腰离开地面，将腿伸直。"
