    "tips": "模仿操的游戏有很多种，每天的宝宝穿鞋子的时候，家 长就可以教他做穿鞋模仿操。儿歌如下：宝宝穿好鞋（两臂下垂站立）分清左右 脚，（两腿叉腰，踢左右腿）鞋带腰系好，（屈膝 90 度，下蹲系鞋带状）能跑又 能跳。（两手叉腰，上跳两次）。教宝宝做模仿操时，要做好一个动作后，再进行 下一个动作。待宝宝熟练后，再独立做一遍。"
