    "tips": "宝宝学刷牙主要是向大人学，因而大人的刷牙习惯也必定 会影响宝宝。有一部分大人采用的是横刷法刷牙，这样会刷伤牙釉的表面并损伤 牙周，而牙缝里的污垢并未清除。家长可以带宝宝到口腔门诊去听课，学习正确 的刷牙方法。"
