    "tips": "书写有一定的年龄限制，例如 1 岁后，从握笔开始练习， 只要求按规定的范围画点、画长线、画短线、画直线、画弯线，接近两岁时要求 使弯线相交，逐渐变成圆形。此时宝宝还不会画直角，4 和7暂时不会写，再过 5～6 个月，这些困难就可以克服。最难分清的是6和9，在3 岁前后能渐渐学会。"
