    "steps": "教孩子唱一些易学易唱的儿童歌曲，注意只限于 5 个音阶 之内，歌词要简短，富有童趣。不宜让宝宝跟着大人唱流行歌曲或电视插曲。如 果音域超过宝宝所能，他会自己把音调降低，久而久之，孩子就会不知不觉地唱 歌走调，不易于改正。\n可以让宝宝跟着音乐学唱，也可以让他同大人一起唱，并且一面唱一面做 动作，使唱歌更加有趣。\n三个音阶的歌曲举例：\n《我出来了》\n1＝D 3／4\n1 3 1 │ 2— ─│ 1 3 1 │ 2— ─│ 1 3 3 │ 1 2 2 │\n我出来 了， 我出来 了， 鸟儿飞 花儿开，\n3 3 2│1— ─│\n多么美 丽。\n1 3 1 │ 2— ─│ 1 3 1 │ 2— ─│1 2 3 │ 3 2 1 │\n我出来 了， 我出来 了， 东跑跑 西跳跳，\n2 3 2 │1— ─‖\n多么快 乐。\n四个音阶的歌曲举例：\n《摇啊摇》\n1=D 4／4\n1 3 2 — │ 1 3 2 — │1 1 2 2 │\n摇 啊 摇， 摇 啊 摇， 我 的 宝 宝\n3 2 1 —│ 1 3 2 —│ 1 3 2 —│\n要 睡 觉， 摇 啊 摇， 摇 啊 摇，\n1 1 2 2 │ 3 — 2 — │ 1 — — 0 ‖\n我 的 宝 宝 睡 着 了。\n五个音阶的歌曲举例：\n## 《春天来》\nI＝F 2／4\n3 3 2 │3 3 2 │ 3 5 5 1 │ 2 — │ 3 3 2 │\n春 天 来，春 天 来，花 儿 朵 朵 开， 红 花 开，\n3 3 2 │3 5 5 1│2 —│3 —│1 —│1 0 ‖\n白 花 开，蜜 蜂 蝴 蝶 都 飞 来!",
    "tips": "大多数两岁的宝宝都会唱歌。有的宝宝既会唱好几首儿童 歌曲，并且吐字还很清楚，甚至会唱一些英语歌曲，不仅声音甜美节拍和音准也 很好。有的宝宝声音粗壮，有的则声音细小，无论唱得如何，大人都要给予鼓励。 暂时唱不好的宝宝，可以先让他跟着大家哼唱，再慢慢一句一句练习，不要剥夺 他跟着大家哼唱的权利。音质的好坏有先天条件也有后天练习的因素，即使先天 条件不好的宝宝，只要家长耐心教，不断地熏陶，同样能培养出喜欢音乐的宝宝。"
