    "steps": "宝宝学习英语有很大潜力，2一3 岁时能记大量词汇，而 且发音准确。不过要经常复 习，不复习就容易忘记。所以最好从日常接触的食 品、图书中的动物、交通工具及人物等学起。先学名词，加上动词和主语就成单 句。平时问安及礼貌语言经常用就容易学会和记牢。 家庭中要常用礼貌语言， 清早起来用英语互相问候“Goodmorning!”；平常家长让宝宝帮忙拿东西时要说 “Please pass me …”，当他递过来时说“Thank you”。并要求宝宝在请求大人 帮忙时说“Please…”，帮忙后也要说“Thankyou”；离开家时要道“Goodbye!”； 睡觉前要道“Good night!”等，从小培养宝宝的文明礼貌习惯及用英语进行交 流的能力",
    "tips": "对于宝宝来说，不论母语、外语都一样。从小反复听什么 语言，就会说什么语言。同时听两种语言，就会说两种语言，乱不了。学外语也 跟学母语一样，可以从小学起，从初生学起，起步越早，学得越好越容易。从小 让宝宝感受到有两种不同的语言系统，有助于将来的进一步学习。也许宝宝学外 语常常是学得快，也忘得快，只要没有使用的机会，不管当时说得怎么好，也会 忘记。可是，在脑海的细胞深处却仍然残留着接受过那种语言的神经网络，深深 的留下了这种痕迹，长大以后重新再声这种语言的时候，就能再度发挥作用。如 果能坚持不断的听和说，将来的学习会更容易。"
