    "tips": "应鼓励宝宝用不同的方法学跳，如连续蹦跳、原地跳、向 前跳、来回跳、学兔子跳等。有些宝宝喜欢看自由体操、芭蕾舞等，也能不知不 觉学会一些动作。跳能使身体轻盈灵活，轻松地越过障碍。跳的方法越多，身体 就越灵活，减少身体受损的可能。"
