    "steps": "两岁的宝宝中有些爱打人，还有一些会咬人，在群体中如 果出现这样的孩子怎么办? 当某个宝宝要打人时，看到的宝宝最好拉开被打的宝 宝，以免两人打起驾来。如果有教师在场，最好让教师来管教打人的孩子。如果 打人的宝宝向自己打来，应当大声叫喊：“打人啦!”“某某要打人啦!”把打人宝 宝的名字喊出来，别人就会看到，打人的宝宝会害怕，此时，最好找地方躲起来， 不让他追到。事后应告诉教师，让她处理此事。咬人的宝宝会突然张嘴把旁边的 宝宝咬一口，看见的宝宝应把此事马上告诉教师。\n教师应组织家长讨论此事，有攻击性的宝宝经常在家受到体罚，就会在群体 中发泄，所以不应当对宝宝进行体罚，可以用严厉的批评代替。例如有些长辈也 被宝宝打，但是长辈们不以为然，招呼。应让宝宝明白打招呼时应当轻轻的，如 果手重就是打人，要受惩罚。\n咬人是对别人直接的伤害，牙齿只能用来吃东西，不能用来咬人。家长可以 让咬人的宝宝体会一下被咬的疼痛（家长适度让宝宝知道疼即可），宝宝受到教 训，就不敢轻易咬人。如果宝宝仍然不改，可以检查是否患异食癖，补充体内缺 乏的元素也许会有帮助，否则可以请心理医生给以检查。",
    "tips": "我们不打架，可以观察宝宝在群体中是哪一种角色，有些 宝宝不但自己不攻击别人，反而能拉开或保护被攻击者，这是最勇敢的一种。另 一种虽然身体不够强健，不能把被攻击者拉开，但会叫大人赶快来帮忙。第三种 只顾自己躲开，免受侵犯，无力去保护别人。第四种是攻击者，主动挑起事端攻 击别人。家长要知道自己的宝宝在群体中是哪一种角色。分析原因，让宝宝在群 体中成为受欢迎的成员，而不是侵犯别人的成员，大家友好礼让、互相帮助，群 体生活才更加愉快。"
