    "prep": "正确握笔、会画“十”字。",
    "duration": "10分钟",
    "steps": "会握蜡笔的宝宝在会画十的基础上很快学会画正方形。 正方形的要求是四个角都是直角。有些宝宝在此基础上还学会画长方形。会画正 方形就可以开始学写汉字了。先学写容易的笔画少的汉字，如一、二、三、十、 上、下、中、人、大、天、土、工、王等汉字。 宝宝最喜欢变戏法，用小黑板 或写字板学习会使宝宝在游戏中学会许多字形相仿的汉字。如一，再添一横成二， 再添一横又成三。人字加一划变大，再加一划又变成天。先划一个十字，在右上 方加一点，去掉下方成上，在十字右下方加一点去掉上边的竖就成为下。一边加 一边讲，再让孩子自己试，宝宝在变戏法的活动中学会了边认边写汉字。又如先 画一个小方形叫口，在当中加一划成日，在旁边加一撇成白，在上面加一横又成 百。相似的汉字放在一起学习会便于分辨，如人和八只差在当中是否合拢。边写 边认易于忘记，要用小字卡写起来再让孩子多次认读，看卡再学写才能巩固效果。 孩子学画正方形，将它拉长就成长方形，如同家中的冰箱。如果将圆形拉长就成 椭圆形。将圆形切开一半就成半圆。如果将正方形斜线切开就成三角形，将正方 形压扁，上下角为锐角，两对角为钝角称为菱形。将正方形或长方形左右两边略 为移动，使个边短，下边长就成为梯形，如同师傅上房顶所用的梯子一样，上小 下大才能放稳。",
