    "tips": "应让宝宝在每次吃饭之前都主动帮妈妈干活，这是一种 很自然的情商训练。此外，宝宝通过摆餐桌还能学会按双数数筷子、按人分盘子、 勺子，饭后分水果等，都是练习数数的机会，这些都是学习知识的活教材。同时 使宝宝成为乐于为人服务，而不是被服务的对象。"
