    "tips": "宝宝必须注意听才能记住，又要看准号码的位置才能拨 对，一旦拨通了对方的电话，会给宝宝一个鼓舞性的惊喜，宝宝会很喜欢给亲人 拨打电话，来考验自己的能力。不少接近3岁的宝宝已经会拨通父母的手机，同 父母通话。"
