    "tips": "木琴本来就是宝宝的玩具，应该让宝宝随便敲着玩，不 要让宝宝感觉到学习的压力。否则宝宝会因为有压力就躲开，不喜欢木琴，就会 失去入门的第一个乐器的功效了。"
