    "steps": "先让宝宝画竖线，在竖线的末端画横线就会出现直角； 再让宝宝画横线，在横线的末端向下画竖线，也会出现直角，把这两个直角合起 来就会变成方形。让宝宝自己练习，只要能画出任何一个直角都要表扬他，也可 以让宝宝在圆形的上方画一个直角，直角向上开口就成兔子的耳朵，直角扣着圆 形就成不倒翁的帽子。用直角构成图会让宝宝很喜欢练习，当宝宝能用两个直角 画出方形时，在正方形下面加上两个小的圆形就能组合成汽车了。让宝宝自己自 由画画，他会画出更多的组合，家长要学会欣赏宝宝画出来的东西，鼓励宝宝用 图形画画。",
