    "tips": "小一点的宝宝可由妈妈帮着剪纸，大一点的宝宝妈妈尽量 让他自己动手，妈妈在旁边做些指导。\n让宝宝观察小鸡和小鸭的图片，看看它们有什么不同(嘴、脚的不同)，告诉 他小鸡的特征是什么。\n小鸡是怎么“出生”的？妈妈可以简单地向宝宝解释，小鸡是怎么从鸡蛋变 成小鸡的。提示宝宝想想，还吃过什么蛋(鸽子蛋、鹌鹑蛋等)，这些蛋是不是也 能孵出小鸽子、小鹌鹑来。"
