    "prep": "自做错图和漏图",
    "duration": "10分钟",
    "steps": "购买专门为 3岁宝宝制作的观察练习图书，如果买不到这 种图书，大人可以用已有的图，巧妙地用纸贴去一部分，让宝宝自己找出来，或 者画一些错图与漏掉某一部分的图让宝宝辨认。首先应让宝宝认识图中之物，然 后告诉他仔细观察图中的每个部位，在判断时，要提醒他考虑到事物的用途和特 点，然后再对照图看看有无错误和遗漏。例如图中有一辆汽车缺了一个轮子，首 先应让宝宝说出图中的物名，再让宝宝看看这辆汽车怎样才能走，当宝宝注意到 要用轮子来跑时，就会发现轮子少了一个，于是找到了缺少的部位。当宝宝发现 错误时，大人应当及时给以表扬，增强宝宝的信心让他乐于参与。",
    "tips": "3 岁的宝宝起码应该看出 5 幅有错误和有遗漏的图，如 果平时大人同宝宝看过类似的图，并一起做过分析讨论，宝宝就会自己去想，找 出错误或遗漏的地方。这种观察和分析问题的方法，能促进宝宝细致、全面的看 问题，从而提高了认知水平。错图和漏图的书籍中，有些图又小又复杂，不宜于 3岁宝宝用。3岁宝宝最好用较大的一图一物，而且只要求在每一幅图中找到一 个问题就够了，不宜让宝宝看过难或有太多疑问的图。如果用图不当，宝宝找了 很长时间也找不出问题，就会使宝宝失去兴趣。给宝宝看的第一幅图应当较容易， 让宝宝得到成功的喜悦，他就会有信心，去找出其他图上的错误和缺漏，在测试 时把容易的放在前面，把较难的放在后面，如果个别宝宝能把比较难的图看出来， 则表示他有很高的解决难题的能力。"
