    "tips": "本测试只做 3 种颜色（红、绿、蓝），因为黄色不容易分 清深浅。如果能买到这种不同深浅能供排序的玩具最好，如果不能买到可以自己 制作，但是要求用完全不吸水的硬纸做卡片。因为如果卡片吸水，吸入的颜色量 有所不同，就不容易做出可以比较颜色深浅的卡片，会让宝宝难于分辨。\n如果分不清卡片的深浅，首先要看卡片制作的质量，然后再考虑宝宝的视力 敏感程度。如果仍有可疑，就要到眼科做进一步的检查。3岁的宝宝都需要检查 眼睛，可以在未去之前自己做游戏测试，找出问题再去眼科就更加方便了。"
