    "tips": "早在 1926 年古迪纳夫就提出可以从儿童自己画的人来判 定儿童的智能，因为孩子所能画出来的是他最有深刻印象的部位，如果能自己画 出来的部位越多孩子就越聪明。到 1963年，哈里斯设计了计算方法，使画人试 验成为通用的智力测试方法。不过我们做了大量的计算发现哈里斯的计算法会使 许多 3～4岁的孩子得高分，而使许多6～7岁的孩子得分过低。他认为3岁才能 画人的1 个部位，每增加1个部位代表3个月的智龄。"
