    "tips": "家长教宝宝欣赏音乐时，常会犯以下错误：\n1、选择的音乐不当 家长随意拿出音乐带就放给宝宝听，不管他爱听不爱听、 能不能理解。\n2、家长在放音乐给宝宝听时，不注意他的情绪 如宝宝正在兴奋地玩耍时， 让他听摇篮曲。\n3、教宝宝欣赏音乐的方法不恰当 只用语言将音乐的内容描述给宝宝听，忽 视让他自己用动作表达对音乐的感受。缺乏经常性 家长有空闲、情绪好时就教 宝宝欣赏音乐，忙或者情绪不好时就中断。\n那么，家长该怎样教孩子欣赏音乐呢？\n1、让宝宝经常听和看家长可以选择一些富有感染力的幼儿歌(乐)曲，把宝 宝带入歌(乐)曲的意境，感受乐曲的情绪。另外，还可以带宝宝欣赏音乐会，从 环境着手，扩大视野，让他感受音乐的氛围。\n2、启动辨别力和想像力 宝宝睡觉前，家长可让他听摇篮曲；情绪高时，可 让他听欢快的歌舞曲……让他感受摇篮曲的温柔、优美，欣赏歌舞曲的欢快、热 烈，逐步训练他的分辨能力和想像力。\n3、可以让宝宝唱一唱，记一记 特别是歌曲，可让他们边听、边唱、边欣赏， 体会内容和情绪。\n4、可以让宝宝随着音乐的节奏和旋律，自由地手舞足蹈让宝宝的创造力在 乐曲的欢乐情景中淋漓尽致、无拘无束地表现出来。"
