/* 按宝宝月龄取课程段：返回 { group, index }；<1 取第 1 段，>36 取最后一段 */
window.getEduCourses = function (monthAge) {
  const list = window.EARLY_EDU_COURSES || [];
  if (!list.length) return { group: null, index: -1 };
  const age = Number(monthAge) || 0;
  if (age < 1) return { group: list[0], index: 0 };
  for (let i = 0; i < list.length; i++) {
    if (age >= list[i].minMonth && age <= list[i].maxMonth) return { group: list[i], index: i };
  }
  return { group: list[list.length - 1], index: list.length - 1 };
};
